import{_ as l,C as e,o as r,c as d,j as s,a as i,E as t,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·断缘","description":"坐忘论第二篇精读：断有为俗事之缘；所断的是机心、名利与攀附，而非一切人事。","frontmatter":{"title":"坐忘论·断缘","description":"坐忘论第二篇精读：断有为俗事之缘；所断的是机心、名利与攀附，而非一切人事。","category":"guide","aliases":["坐忘论断缘","断缘二","坐忘论精读之三"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-02.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-02.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-02.md"};function c(u,a,b,m,x,v){const p=e("DaoReadingPrelude"),n=e("DaoTextReading"),o=e("DaoKeywordCards");return r(),d("div",null,[a[0]||(a[0]=s("h1",{id:"坐忘论·断缘",tabindex:"-1"},[i("坐忘论·断缘 "),s("a",{class:"header-anchor",href:"#坐忘论·断缘","aria-label":'Permalink to "坐忘论·断缘"'},"​")],-1)),t(p,{title:"断的是机心之缘，不是一切人情",summary:"【敬信】解决「是否真正认定修道」，【断缘】则要求把这份认定落实到现实生活。信道却仍不断经营名声、关系、利益与机会，心神便持续被外事牵引——所以先减少使心向外活动的条件，再谈心如何安住。",points:[{label:"说所断",text:"显德露能、遗问庆吊、假隐逸、酒食邀致——皆巧蕴机心，以干时利。"},{label:"说方法",text:"不唱不和，旧缘渐断、新缘莫结，使利益之交自然日疏。"},{label:"说底线",text:"事有不可废者，不得已而行之，勿遂生爱、系心为业。"}],hint:"此篇可与《天隐子·安处》对读：一在断外缘，一在调环境，都是为收心先清出一块地方。"}),a[1]||(a[1]=s("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),s("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=s("p",null,[s("strong",null,"一、断缘的定义与作用")],-1)),t(n,{paragraphs:["断缘者，断有为俗事之缘也。弃事则形不劳，无为则心自安，恬简日就，尘累日薄，迹弥远俗，心弥近道，至圣至神，孰不由此乎。经云：塞其兑，闭其门，终身不勤。"]}),a[3]||(a[3]=s("p",null,[s("strong",null,"二、四类应当断除的俗缘")],-1)),t(n,{paragraphs:["或显德露能，求人保己；或遗问庆吊，以事往还；或假隐逸，情希升进；或酒食邀致，以望后恩。斯乃巧蕴机心，以干时利，既非顺道，深妨正业。凡此类例，皆应绝之。"]}),a[4]||(a[4]=s("p",null,[s("strong",null,"三、不唱不和，使缘渐疏")],-1)),t(n,{paragraphs:["经云：开其兑，济其事，终身不救。我但不唱，彼自不和；彼虽有唱，我不和之。旧缘渐断，新缘莫结，醴交势合，自致日疏，无事安闲，方可修道。"]}),a[5]||(a[5]=s("p",null,[s("strong",null,"四、《庄子》的「不将不迎」")],-1)),t(n,{paragraphs:["庄云：不将不迎，无为交俗之情。又云：无为谋府，无为事任，无为知主。"]}),a[6]||(a[6]=s("p",null,[s("strong",null,"五、不可废之事如何处理")],-1)),t(n,{paragraphs:["若事有不可废者，不得已而行之，勿遂生爱，系心为业。"]}),a[7]||(a[7]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[i("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),t(o,{items:[{term:"缘",pinyin:["yuán"],meaning:"使人与某人、某事相连并持续牵引身心的关系与条件。不只是一次接触，更是「事情在心中继续延续、并引出新的欲望与行动」。"},{term:"有为",pinyin:["yǒu","wéi"],meaning:"此处非泛指一切行动，而是由私心造作推动的活动——为显名而表现、为受保护而依附、为回报而宴请之类。"},{term:"恬简",pinyin:["tián","jiǎn"],meaning:"恬，安静淡泊不躁竞；简，简少不繁杂。「日就」谓一天天形成，非一夕可得。"},{term:"尘累",pinyin:["chén","lěi"],meaning:"尘，尘俗，亦喻遮蔽心性者；累，牵累系缚。日薄，谓一天天变淡——不只看事情多少，更看事情在心中占多少位置。"},{term:"迹弥远俗",pinyin:["jì","mí","yuǎn","sú"],meaning:"迹，外在行为行迹；弥，越发。外在越远离世俗机巧追逐，内心越接近大道——所远者是「俗情」，不只是「俗地」。"},{term:"塞其兑，闭其门",pinyin:["sāi","qí","duì","bì","qí","mén"],meaning:"《道德经》第五十二章。兑指孔窍、感官与外相通的门户。非封闭感官，而是不让感知立刻发展为内心的追逐。"},{term:"终身不勤",pinyin:["zhōng","shēn","bù","qín"],meaning:"勤，劳苦困乏。谓不因无穷事务而终身劳困，非提倡懒惰。"},{term:"显德露能",pinyin:["xiǎn","dé","lù","néng"],meaning:"显露德行与才能以求人保护。批评的不在「有」德能，而在「显」「露」背后的目的。与《得道》「含光藏辉」相对。"},{term:"遗问庆吊",pinyin:["wèi","wèn","qìng","diào"],meaning:"遗问，遣人问候馈赠（依底本保留此字）；庆吊，贺喜与吊丧。此处指借礼节往来维持利益关系。"},{term:"假隐逸，情希升进",pinyin:["jiǎ","yǐn","yì","qíng","xī","shēng","jìn"],meaning:"表面隐居退让，内心期待升迁进用。四类俗缘中最具讽刺的一类：以退为进，外表无为而内心有为。"},{term:"机心",pinyin:["jī","xīn"],meaning:"算计、谋利、操控结果之心。特征：外在理由与内在目的不同；把他人当作实现目标的工具；以礼、德、隐逸等高尚形式包装私利。"},{term:"干时利",pinyin:["gān","shí","lì"],meaning:"干，求取；时利，当时现实中的名位、机会与利益。时利不稳定，心若建立其上便须随时局不断忧惧经营。"},{term:"正业",pinyin:["zhèng","yè"],meaning:"此处指修道本业。机心交往会妨此正业，所以说「深妨」。"},{term:"开其兑，济其事",pinyin:["kāi","qí","duì","jì","qí","shì"],meaning:"与「塞其兑」相反：向感官欲望敞开，并增加、扩张种种事务，则「终身不救」。"},{term:"唱、和",pinyin:["chàng","hè"],meaning:"唱，首先发起；和，响应配合。「我但不唱，彼自不和；彼虽有唱，我不和之」——断缘的方法不是决裂，而是停止提供动力。"},{term:"醴交势合",pinyin:["lǐ","jiāo","shì","hé"],meaning:"醴，甜酒（依底本作「醴」）。醴交，以酒食款待相结；势合，因权势利益相合。皆非道义性情之交，利益条件消失便自然淡去。"},{term:"不将不迎",pinyin:["bù","jiāng","bù","yíng"],meaning:"《庄子·应帝王》「至人之用心若镜，不将不迎，应而不藏」。将，迎送追随；迎，预先迎取。如镜：物未至不预想，物来如实映照，物去不留影。"},{term:"谋府",pinyin:["móu","fǔ"],meaning:"计谋聚集的府库。无为谋府，谓不使心成为盘算的常态仓库，非谓不能正常思考。"},{term:"事任",pinyin:["shì","rèn"],meaning:"把事务全部揽在自己身上。无为事任，非拒绝责任，而是不把所有事都揽成自己的任务——与《简事》「事物称万，不独委于一人」相通。"},{term:"知主",pinyin:["zhī","zhǔ"],meaning:"知通「智」。无为知主，谓不让机巧聪明成为生命的主人；不消灭智慧，而让它回到辅助位置。"},{term:"不得已而行之",pinyin:["bù","dé","yǐ","ér","xíng","zhī"],meaning:"行动来自事情本身的必要性，而非个人欲望的扩张——是一种有限、有界的行动。"},{term:"系心为业",pinyin:["jì","xīn","wéi","yè"],meaning:"把心系缚在事务上，使其成为不断延续的业。业不只取决于外在做了什么，更取决于心如何依附。"}]}),a[8]||(a[8]=h("",116))])}const q=l(g,[["render",c]]);export{y as __pageData,q as default};
